@Isolated("Scopes process-wide calibration consumption for deterministic JFR decisions")
class NativeStrategyDecisionDiagnosticsTest {

	private static final String EVENT = "org.eclipse.rdf4j.lmdb.NativeStrategyDecision";

	private String previousCalibration;

	@BeforeEach
	void isolateCalibration() {
		// These fixtures exercise diagnostic capture, not costs learned by unrelated queries.
		previousCalibration = System.getProperty(LmdbNativeCostCalibration.ENABLED_PROPERTY);
		System.setProperty(LmdbNativeCostCalibration.ENABLED_PROPERTY, "false");
	}

	@AfterEach
	void restoreCalibration() {
		if (previousCalibration == null) {
			System.clearProperty(LmdbNativeCostCalibration.ENABLED_PROPERTY);
		} else {
			System.setProperty(LmdbNativeCostCalibration.ENABLED_PROPERTY, previousCalibration);
		}
	}

	@Test
	void decisionQuotesRetainTheSingleRankedBatchAndCompleteLegalInventory(@TempDir Path directory) throws Exception {
		AtomicInteger wallReads = new AtomicInteger();
		LmdbNativeStoreCostModel store = new LmdbNativeStoreCostModel(null, LmdbNativePosteriorConfig.defaults(),
				LmdbNativeProbeConfig.defaults(), () -> 1000L + wallReads.incrementAndGet(), System::nanoTime);
		LmdbNativeMachineCostModel machine = new LmdbNativeMachineCostModel();
		LmdbNativeAdaptiveCostModel model = new LmdbNativeAdaptiveCostModel(machine, store,
				new LmdbNativeAdaptiveCostModel.Configuration(true, true));
		LmdbNativeStrategyProposal<String> winner = proposal("irAggregateParallel", 20D, () -> "rows");
		LmdbNativeStrategyProposal<String> dominated = proposal("adjacencyAggregate", 30D, () -> "unused");
		dominated.physicallyDominatedBy(winner, "same input plus additional materialization");
		LmdbNativeCostEstimate winnerEstimate = winner.adaptiveEstimate(-1D);
		assertThat(model.predict(winnerEstimate).priceBasis()).as("cold features have no numerical authority")
				.isEqualTo(LmdbNativeCostPrediction.PriceBasis.ORDINAL_ONLY);
		for (int sample = 0; sample < LmdbNativeMachineCostModel.MINIMUM_ADAPTIVE_SAMPLES; sample++) {
			assertThat(machine.update(winnerEstimate.total(), 500D).accepted()).isTrue();
		}
		LmdbNativeCostPrediction numericalControl = model.predict(winnerEstimate);
		assertThat(numericalControl.uniformlyPriceable()).as("the ranked fixture needs genuinely supported features")
				.isTrue();
		assertThat(numericalControl.exactCompletedCount()).as("machine training must not invent exact-arm completions")
				.isZero();
		Path output = directory.resolve("decision-quotes.jfr");
		try (Recording recording = recording();
				LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forModel(null, -1D, model)) {
			arbiter.offer(() -> winner)
					.offer(() -> dominated)
					.offer(() -> new LmdbNativeStrategyProposal<>(() -> "unknown", Double.NaN, "nestedLoop"))
					.offer(() -> {
						LmdbNativeAttemptMetrics.recordDecline(null, "batch", "unsupported fixture shape");
						return null;
					});
			wallReads.set(0);
			try (LmdbNativeStrategySelection<String> selected = arbiter.selectWithObservation()) {
				assertThat(selected.value()).isEqualTo("rows");
				assertThat(wallReads).hasValue(1);
				selected.exhausted();
			}
			recording.stop();
			recording.dump(output);
		}
		List<RecordedEvent> quotes = phase(events(output), "CANDIDATE");
		assertThat(quotes).as("one immutable record for every legal arm and explicit structural decline").hasSize(4);
		RecordedEvent selected = strategy(quotes, "irAggregateParallel");
		assertThat(selected.getString("status")).isEqualTo("SELECTED");
		assertThat(selected.getBoolean("offered")).isTrue();
		assertThat(selected.getBoolean("predictionPresent")).isTrue();
		assertThat(selected.getBoolean("priceKnown")).isTrue();
		assertThat(selected.getLong("quoteMillis")).isEqualTo(1001L);
		assertThat(selected.getLong("exactCompletedCount")).isZero();
		assertThat(selected.getString("variant")).isEqualTo(winner.adaptiveEstimate(-1D).variantKey().toString());
		assertThat(selected.getDouble("expectedNanos")).isPositive();
		assertThat(selected.getDouble("expectedNanos")).isEqualTo(numericalControl.expectedNanos());
		assertThat(selected.getDouble("low95Nanos")).isEqualTo(numericalControl.low95Nanos());
		assertThat(selected.getDouble("high95Nanos")).isEqualTo(numericalControl.high95Nanos());
		assertThat(selected.getDouble("low95Nanos")).isLessThanOrEqualTo(selected.getDouble("expectedNanos"));
		assertThat(selected.getDouble("high95Nanos")).isGreaterThanOrEqualTo(selected.getDouble("expectedNanos"));
		assertThat(selected.getString("regime")).isNotEmpty();
		assertThat(selected.getString("predictionReason")).isNotNull();
		assertThat(selected.getString("executionMode"))
				.isEqualTo(winner.adaptiveEstimate(-1D).variantKey().executionMode().name());
		assertThat(selected.getString("compilationCacheState")).isEqualTo("NOT_APPLICABLE");
		assertThat(selected.getInt("workerBucket")).isZero();
		assertThat(selected.getBoolean("requiresHashing")).isFalse();
		assertThat(selected.getBoolean("learnedDominanceAllowed"))
				.isEqualTo(numericalControl.learnedDominanceAllowed());
		assertAll("dominance, unknown pricing, absence and completed observation are independent contracts",
				() -> {
					RecordedEvent dominatedQuote = strategy(quotes, "adjacencyAggregate");
					assertThat(dominatedQuote.getString("status")).isEqualTo("PHYSICALLY_DOMINATED");
					assertThat(dominatedQuote.getString("availabilityReason"))
							.isEqualTo("irAggregateParallel: same input plus additional materialization");
				},
				() -> {
					RecordedEvent unknown = strategy(quotes, "nestedLoop");
					assertThat(unknown.getBoolean("offered")).isTrue();
					assertThat(unknown.getBoolean("priceKnown")).isFalse();
					assertThat(unknown.getString("priceBasis")).isEqualTo("ORDINAL_ONLY");
				},
				() -> {
					RecordedEvent absent = strategy(quotes, "batch");
					assertThat(absent.getBoolean("offered")).isFalse();
					assertThat(absent.getBoolean("predictionPresent")).isFalse();
					assertThat(absent.getString("availabilityReason")).isEqualTo("unsupported fixture shape");
				},
				() -> assertThat(phase(events(output), "OBSERVATION")).singleElement().satisfies(event -> {
					assertThat(event.getString("status")).isEqualTo("EXHAUSTED");
					assertThat(event.getBoolean("trainingEligible")).isTrue();
					// The fixture drains without reporting one physical counter: its direct timing is retained,
					// but estimated feature totals never train the machine coefficients as measured work.
					assertThat(event.getBoolean("trainingAccepted")).isFalse();
					assertThat(event.getString("trainingReason"))
							.contains("neither measured nor independently owned");
					assertThat(event.getLong("quoteMillis")).isEqualTo(selected.getLong("quoteMillis"));
					assertThat(event.getLong("exactCompletedCount")).isZero();
				}));
	}

	@Test
	void openReturnedDoesNotBecomeCompletionAndCancellationNeverEarnsSuccess(@TempDir Path directory) throws Exception {
		LmdbNativeStoreCostModel store = new LmdbNativeStoreCostModel();
		Path output = directory.resolve("cancelled-observation.jfr");
		try (Recording recording = recording();
				LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forModel(null, -1D,
						model(store))) {
			arbiter.offer(() -> proposal("irAggregate", 12D, () -> "cursor"));
			try (LmdbNativeStrategySelection<String> selected = arbiter.selectWithObservation()) {
				assertThat(selected.observation().snapshot().completion())
						.isEqualTo(LmdbNativeCostObservation.Completion.OPEN);
				selected.cancelled(null);
				selected.exhausted();
			}
			recording.stop();
			recording.dump(output);
		}
		List<RecordedEvent> recorded = events(output);
		assertThat(phase(recorded, "ATTEMPT")).singleElement()
				.satisfies(event -> assertThat(event.getString("status")).isEqualTo("OPEN_RETURNED"));
		assertThat(phase(recorded, "OBSERVATION")).singleElement().satisfies(event -> {
			assertThat(event.getString("status")).isEqualTo("CANCELLED");
			assertThat(event.getBoolean("trainingEligible")).isFalse();
			assertThat(event.getBoolean("trainingAccepted")).isFalse();
		});
		assertThat(store.latestObserved().size()).isZero();
	}

	@Test
	void forcedDeclineKeepsItsOwnReasonAcrossFallbackAndNestedCapture(@TempDir Path directory) throws Exception {
		Path output = directory.resolve("declined-attempt.jfr");
		try (Recording recording = recording();
				LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forModel(null, -1D,
						model(new LmdbNativeStoreCostModel()))) {
			arbiter.offer(() -> proposal("irAggregate", 12D, () -> {
				try (LmdbNativeStrategyArbiter<String> nested = LmdbNativeStrategyArbiter.forExpr(null)) {
					nested.offer(() -> new LmdbNativeStrategyProposal<>(() -> "nested", 1D, "batch"));
					assertThat(nested.select()).isEqualTo("nested");
				}
				LmdbNativeAttemptMetrics.recordDecline(null, "irAggregate", "COMPILE_PENDING[fixture]");
				return null;
			}));
			arbiter.offer(() -> proposal("nestedLoop", 20D, () -> "fallback"));
			assertThat(arbiter.select()).isEqualTo("fallback");
			recording.stop();
			recording.dump(output);
		}
		List<RecordedEvent> attempts = phase(events(output), "ATTEMPT");
		RecordedEvent decline = strategy(attempts, "irAggregate");
		assertThat(decline.getString("status")).isEqualTo("DECLINED");
		assertThat(decline.getString("availabilityReason")).isEqualTo("COMPILE_PENDING[fixture]");
		assertThat(decline.getBoolean("trainingAccepted")).isFalse();
		assertThat(strategy(attempts, "nestedLoop").getString("status")).isEqualTo("OPEN_RETURNED");
		assertThat(strategy(attempts, "batch").getLong("decisionId")).isNotEqualTo(decline.getLong("decisionId"));
	}

	@Test
	void forcedInventoryPreservesRejectedArmsAndDistinguishesMissingForcedShape(@TempDir Path directory)
			throws Exception {
		Path output = directory.resolve("forced-inventory.jfr");
		try (Recording recording = recording()) {
			try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.<String>forModel(null, -1D,
					model(new LmdbNativeStoreCostModel())).forcing("nestedLoop", "forced fixture")) {
				arbiter.offer(() -> proposal("irAggregate", 1D, () -> "unused"));
				arbiter.offer(() -> proposal("nestedLoop", 100D, () -> "forced"));
				assertThat(arbiter.select()).isEqualTo("forced");
			}
			try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.<String>forExpr(null)
					.forcing("irAggregate", "missing fixture")) {
				arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> "unused", 1D, "nestedLoop"));
				assertThatThrownBy(arbiter::select).isInstanceOf(QueryEvaluationException.class)
						.hasMessageContaining("never a candidate");
			}
			recording.stop();
			recording.dump(output);
		}
		List<RecordedEvent> quotes = phase(events(output), "CANDIDATE");
		RecordedEvent forcedOut = quotes.stream()
				.filter(event -> "irAggregate".equals(event.getString("strategy")))
				.filter(event -> event.getBoolean("offered"))
				.findFirst()
				.orElseThrow();
		assertThat(forcedOut.getString("status")).isEqualTo("FORCED_OUT");
		assertThat(forcedOut.getBoolean("predictionPresent")).isFalse();
		assertThat(forcedOut.getString("forcedStrategy")).isEqualTo("nestedLoop");
		assertThat(forcedOut.getBoolean("forceMandatory")).isTrue();
		assertThat(quotes.stream()
				.filter(event -> "irAggregate".equals(event.getString("strategy")))
				.filter(event -> !event.getBoolean("offered"))).singleElement().satisfies(event -> {
					assertThat(event.getString("status")).isEqualTo("NOT_OFFERED");
					assertThat(event.getBoolean("predictionPresent")).isFalse();
				});
		assertThat(phase(events(output), "ATTEMPT")).singleElement()
				.satisfies(event -> assertThat(event.getString("strategy")).isEqualTo("nestedLoop"));
	}

	@Test
	void failedAndCancelledOpenersKeepTheOriginalFailureWithoutTraining(@TempDir Path directory) throws Exception {
		Path output = directory.resolve("failed-openers.jfr");
		IllegalStateException failure = new IllegalStateException("fixture opener failed");
		try (Recording recording = recording()) {
			for (RuntimeException problem : List.of(failure, KernelQueryCancelledException.INSTANCE)) {
				try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forModel(null, -1D,
						model(new LmdbNativeStoreCostModel()))) {
					arbiter.offer(() -> proposal("irAggregate", 12D, () -> {
						throw problem;
					}));
					assertThatThrownBy(arbiter::select).isSameAs(problem);
				}
			}
			recording.stop();
			recording.dump(output);
		}
		assertThat(phase(events(output), "ATTEMPT")).extracting(event -> event.getString("status"))
				.containsExactlyInAnyOrder("FAILED", "CANCELLED");
		assertThat(phase(events(output), "OBSERVATION")).hasSize(2).allSatisfy(event -> {
			assertThat(event.getBoolean("trainingEligible")).isFalse();
			assertThat(event.getBoolean("trainingAccepted")).isFalse();
		});
		assertThat(phase(events(output), "OBSERVATION")).extracting(event -> event.getString("status"))
				.containsExactlyInAnyOrder("FAILED", "CANCELLED");
	}

	@Test
	void nestedBoundariesRetainTheInvocationOwnerAcrossWorkerThreads(@TempDir Path directory) throws Exception {
		Path output = directory.resolve("nested-owners.jfr");
		AtomicLong ownerId = new AtomicLong();
		AtomicLong evaluationId = new AtomicLong();
		try (Recording recording = recording();
				var owner = Executors.newSingleThreadExecutor();
				var worker = Executors.newSingleThreadExecutor()) {
			owner.submit(() -> {
				NativeCancellationToken root = new NativeCancellationToken();
				ownerId.set(Thread.currentThread().threadId());
				evaluationId.set(root.evaluationId());
				try (LmdbNativeStrategyArbiter<String> outer = LmdbNativeStrategyArbiter.<String>forModel(null, -1D,
						model(new LmdbNativeStoreCostModel())).diagnostics(root, 100L, "outer group")) {
					outer.offer(() -> proposal("irAggregate", 12D, () -> {
						try {
							return worker.submit(() -> {
								NativeCancellationToken child = new NativeCancellationToken(root);
								try (LmdbNativeStrategyArbiter<String> inner = LmdbNativeStrategyArbiter
										.<String>forModel(null, -1D,
												model(new LmdbNativeStoreCostModel()))
										.diagnostics(child, 101L, "inner group")) {
									inner.offer(() -> proposal("nestedLoop", 3D, () -> "nested rows"));
									return inner.select();
								}
							}).get();
						} catch (Exception problem) {
							throw new IllegalStateException(problem);
						}
					}));
					assertThat(outer.select()).isEqualTo("nested rows");
				}
				return null;
			}).get();
			recording.stop();
			recording.dump(output);
		}
		List<RecordedEvent> recorded = events(output);
		assertThat(recorded).hasSize(6).allSatisfy(event -> {
			assertThat(event.getLong("evaluationId")).isEqualTo(evaluationId.get());
			assertThat(event.getLong("ownerThreadId")).isEqualTo(ownerId.get());
		});
		assertThat(phase(recorded, "CANDIDATE")).extracting(event -> event.getLong("boundaryId"))
				.containsExactlyInAnyOrder(100L, 101L);
		RecordedEvent inner = strategy(phase(recorded, "ATTEMPT"), "nestedLoop");
		assertThat(inner.getThread().getJavaThreadId()).isNotEqualTo(ownerId.get());
	}

	private static LmdbNativeAdaptiveCostModel model(LmdbNativeStoreCostModel store) {
		return new LmdbNativeAdaptiveCostModel(new LmdbNativeMachineCostModel(), store,
				new LmdbNativeAdaptiveCostModel.Configuration(true, true));
	}

	private static LmdbNativeStrategyProposal<String> proposal(String strategy, double work,
			LmdbNativeStrategyProposal.Opener<String> opener) {
		LmdbNativeStrategyProposal<String> proposal = new LmdbNativeStrategyProposal<>(opener, work, strategy);
		LmdbNativeCostVector vector = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.OUTPUT_MATERIALIZATION,
				work);
		return proposal.withPhysicalEstimate(new LmdbNativeCostEstimate(
				LmdbNativePhysicalVariantKey.builder(strategy).build(), LmdbNativeCostVector.zero(), vector, work, 0D));
	}

	private static Recording recording() {
		Recording recording = new Recording();
		recording.enable(EVENT).withThreshold(Duration.ZERO);
		recording.start();
		return recording;
	}

	private static List<RecordedEvent> events(Path output) throws Exception {
		return RecordingFile.readAllEvents(output)
				.stream()
				.filter(event -> EVENT.equals(event.getEventType().getName()))
				.toList();
	}

	private static List<RecordedEvent> phase(List<RecordedEvent> events, String phase) {
		return events.stream().filter(event -> phase.equals(event.getString("phase"))).toList();
	}

	private static RecordedEvent strategy(List<RecordedEvent> events, String strategy) {
		return events.stream()
				.filter(event -> strategy.equals(event.getString("strategy")))
				.findFirst()
				.orElseThrow(() -> new AssertionError("missing diagnostic for " + strategy));
	}
}
